package net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueobject.LoginVO;

class LoginValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of login of smtp outbound config")
  void test_login_value_holder_assign_plain_value() {
    Object holder = new Object();
    LoginValueHolder<Object> value = new LoginValueHolder<>(holder);
    Assertions.assertSame(holder, value.login("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getLoginValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getLogin().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of login of smtp outbound config")
  void test_login_value_holder_assign_value_object() {
    Object holder = new Object();
    LoginValueHolder<Object> value = new LoginValueHolder<>(holder);
    LoginVO vo = LoginVO.from("one");
    Assertions.assertFalse(value.getLoginValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.login(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLoginValue().orElseThrow());
    Assertions.assertSame(holder, value.login(Optional.empty()));
    Assertions.assertFalse(value.getLoginValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.login(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLoginValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of login of smtp outbound config against the original")
  void test_login_value_holder_read() {
    Object holder = new Object();
    LoginValueHolder<Object> value = new LoginValueHolder<>(holder);
    LoginVO vo = LoginVO.from("one");
    LoginVO other = LoginVO.from("one");
    SmtpOutboundConfig original = Mockito.mock(SmtpOutboundConfig.class);
    Mockito.when(original.getLoginValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLogin(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readLogin(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.login(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLogin(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLogin(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of login of smtp outbound config")
  void test_login_value_holder_unset() {
    Object holder = new Object();
    LoginValueHolder<Object> value = new LoginValueHolder<>(holder);
    LoginVO vo = LoginVO.from("one");
    value.login(vo);
    Assertions.assertSame(holder, value.unsetLoginIfMatches("login_other"));
    Assertions.assertTrue(value.getLoginValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLoginIfMatches("login"));
    Assertions.assertFalse(value.getLoginValue().isPresent(),
        "The field name must clear the value");
    value.login(vo);
    Assertions.assertSame(holder, value.unsetLogin());
    Assertions.assertFalse(value.getLoginValue().isPresent(), "Unset must clear the value");
  }
}
